// ===========================================================================
// Code node "Evaluar" — alertas de infraestructura
// monitoreo-simple · https://github.com/fampalio/monitoreo-simple
//
// Entrada:  items de "Parsear métricas" (un JSON por servidor)
//           items de "Parsear estado"   (state.json de la corrida anterior)
// Salida:   1 item { hasAlerts, message, state, summary }
//
// Regla central: sólo se avisa en las TRANSICIONES. Un disco al 90% genera
// un mensaje cuando cruza el umbral y otro cuando se normaliza. Nada en el
// medio. Sin esto son 288 mensajes por día y terminás silenciando el canal.
// ===========================================================================

// --------------------------- configuración --------------------------------
// REEMPLAZAR por los tuyos (`hostname -s` de cada uno). Un host que está acá
// y no reporta dispara "sin datos"; uno que reporta y no está, se ignora.
const SERVERS = ['srv-a', 'srv-b', 'srv-c'];   // hosts que SE ESPERAN reportando

const TH = {
  diskWarn: 70,   // disco: avisa temprano, crece despacio y da tiempo a actuar
  diskCrit: 85,
  memCrit: 90,    // RAM y CPU sólo en crítico: en warn son ruido transitorio
  cpuCrit: 95,
  certWarn: 21,   // días para vencimiento TLS
  certCrit: 7,
  staleSec: 15 * 60,   // sin reportar => el recolector murió
  loadFactor: 2.5      // load1 > cores * factor
};

// --------------------------- helpers --------------------------------------
const now = Math.floor(Date.now() / 1000);

// extractFromFile puede dejar el contenido en .data (objeto o string) o en la
// raíz del json, según versión y configuración del nodo. `mustHave` distingue
// un JSON de métricas (trae "host") de uno de estado (trae "issues"): sin eso
// el estado previo se descarta y toda corrida parece la primera.
function unwrap(item, mustHave) {
  const j = (item && item.json) ? item.json : {};

  const candidatos = [];
  if (j.data && typeof j.data === 'object') candidatos.push(j.data);
  if (typeof j.data === 'string') {
    try { candidatos.push(JSON.parse(j.data)); } catch (e) { /* no era JSON */ }
  }
  candidatos.push(j);

  for (const c of candidatos) {
    if (c && typeof c === 'object' && c[mustHave] !== undefined) return c;
  }
  return null;
}

// --------------------------- 1. métricas actuales -------------------------
let metrics = [];
try {
  metrics = $('Parsear métricas').all().map(i => unwrap(i, 'host')).filter(Boolean);
} catch (e) {
  metrics = [];
}

const byHost = {};
for (const m of metrics) {
  if (m && m.host) byHost[m.host] = m;
}

// --------------------------- 2. estado anterior ---------------------------
// `seen` distingue "nunca corrí" de "corrí y estaba todo sano". Sin esa
// diferencia, la primera corrida sin problemas haría que la SEGUNDA vuelva a
// tratarse como línea de base y se coma la primera alerta real.
let prev = {};
let seen = false;
try {
  const stateItems = $('Parsear estado').all();
  const s = stateItems.length ? unwrap(stateItems[0], 'issues') : null;
  if (s && s.issues && typeof s.issues === 'object') {
    prev = s.issues;
    seen = true;
  }
} catch (e) {
  prev = {};   // primera corrida, o el archivo todavía no existe
}
const firstRun = !seen;

// --------------------------- 3. detectar problemas ------------------------
// Cada problema tiene una clave estable. La clave es lo que se compara entre
// corridas, así que tiene que identificar el problema, no su valor puntual.
const current = {};

// `what` es el nombre corto y estable del problema (sin valores): es lo que se
// usa al anunciar la recuperación, porque "Normalizado — disco al 91%" no se
// entiende. `detalle` es el texto con números para la alerta inicial.
function raise(key, level, host, what, detalle) {
  current[key] = { level, host, what, detalle, since: prev[key]?.since ?? now };
}

for (const host of SERVERS) {
  const m = byHost[host];

  // 3.1 y 3.2 comparten la clave `:down` a propósito. "No reporta hace 1 h" y
  // "falta el JSON" son el mismo problema — el host no está diciendo nada — y
  // separarlos hace que pasar de uno a otro dispare una alerta nueva y un
  // "normalizado" del mismo host en el mismo mensaje.
  if (!m) {
    raise(`${host}:down`, 'crit', host, 'disponibilidad', 'sin datos (falta el JSON)');
    continue;
  }

  const age = now - (Number(m.timestamp) || 0);
  if (age > TH.staleSec) {
    const mins = Math.floor(age / 60);
    raise(`${host}:down`, 'crit', host, 'disponibilidad',
      `no reporta hace ${mins >= 60 ? Math.floor(mins / 60) + ' h' : mins + ' min'}`);
    // Si los datos son viejos, el resto de las métricas tampoco sirven.
    continue;
  }

  // 3.3 servicios caídos (una clave por servicio: no se pisan entre sí)
  for (const s of (Array.isArray(m.services) ? m.services : [])) {
    if (s.state === 'inactive') {
      raise(`${host}:svc:${s.name}`, 'crit', host, `servicio ${s.name}`, `servicio caído: ${s.name}`);
    }
  }

  // 3.4 disco
  const disk = Number(m.disk?.percent ?? 0);
  if (disk >= TH.diskWarn) {
    raise(`${host}:disk`, disk >= TH.diskCrit ? 'crit' : 'warn', host, 'disco',
      `disco al ${disk}% (${m.disk?.used_gb}/${m.disk?.total_gb} GB)`);
  }

  // 3.5 memoria
  const mem = Number(m.memory?.percent ?? 0);
  if (mem >= TH.memCrit) {
    raise(`${host}:mem`, 'crit', host, 'RAM',
      `RAM al ${mem}% (${m.memory?.used_gb}/${m.memory?.total_gb} GB)`);
  }

  // 3.6 CPU
  const cpu = Number(m.cpu?.percent ?? 0);
  if (cpu >= TH.cpuCrit) {
    raise(`${host}:cpu`, 'crit', host, 'CPU', `CPU al ${cpu}%`);
  }

  // 3.7 load sostenido
  const load1 = Number(m.cpu?.load1 ?? 0);
  const cores = Number(m.cpu?.cores ?? 1);
  if (load1 > cores * TH.loadFactor) {
    raise(`${host}:load`, 'crit', host, 'load',
      `load ${load1} con ${cores} core${cores === 1 ? '' : 's'}`);
  }

  // 3.8 certificado TLS
  const cert = m.cert_days_left;
  if (cert !== null && cert !== undefined) {
    const d = Number(cert);
    if (d < TH.certWarn) {
      raise(`${host}:cert`, d < TH.certCrit ? 'crit' : 'warn', host, 'certificado TLS',
        `certificado TLS${m.cert_name ? ' ' + m.cert_name : ''} vence en ${d} día${d === 1 ? '' : 's'}`);
    }
  }
}

// --------------------------- 4. comparar con el estado previo -------------
const RANK = { warn: 1, crit: 2 };

const nuevos = [];      // no existía antes
const escalados = [];   // existía en warn y ahora está en crit
const resueltos = [];   // existía y ya no

for (const [key, iss] of Object.entries(current)) {
  const before = prev[key];
  if (!before) {
    nuevos.push(iss);
  } else if (RANK[iss.level] > RANK[before.level]) {
    escalados.push(iss);
  }
  // mismo nivel que antes => silencio deliberado
}

for (const [key, before] of Object.entries(prev)) {
  if (!current[key]) {
    const mins = Math.floor((now - (before.since || now)) / 60);
    resueltos.push({
      host: before.host,
      // Los estados guardados por una versión anterior no traen `what`.
      what: before.what || before.title || 'el problema',
      dur: mins >= 60 ? `${Math.floor(mins / 60)} h` : `${mins} min`
    });
  }
}

// --------------------------- 5. armar el mensaje --------------------------
// En la primera corrida no se avisa de lo que ya estaba mal: se toma como
// línea de base. Si no, al importar el workflow te llega el inventario
// completo de problemas viejos como si acabaran de pasar.
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const linea = (iss, icono) =>
  `${icono} <b>${esc(iss.host)}</b> — ${esc(iss.detalle)}`;

const lines = [];

if (firstRun) {
  const n = Object.keys(current).length;
  lines.push('<b>🔧 Monitoreo iniciado</b>');
  lines.push(n
    ? `Línea de base: ${n} problema${n === 1 ? '' : 's'} ya presente${n === 1 ? '' : 's'}. No se alerta sobre esto, sólo sobre lo que cambie de acá en adelante.`
    : 'Todos los servidores están sanos.');
  for (const iss of Object.values(current)) {
    lines.push('   ' + linea(iss, iss.level === 'crit' ? '🔴' : '🟡'));
  }
} else {
  for (const iss of nuevos) {
    lines.push(linea(iss, iss.level === 'crit' ? '🔴' : '🟡'));
  }
  for (const iss of escalados) {
    lines.push(linea(iss, '🔺') + ' <i>(escaló a crítico)</i>');
  }
  for (const r of resueltos) {
    lines.push(`✅ <b>${esc(r.host)}</b> — ${esc(r.what)} OK de nuevo <i>(estuvo ${r.dur})</i>`);
  }
}

const hasAlerts = firstRun ? true : (nuevos.length + escalados.length + resueltos.length) > 0;

let message = '';
if (hasAlerts) {
  const header = firstRun
    ? ''
    : `<b>⚠️ Infraestructura</b>\n`;
  message = header + lines.join('\n');
}

// --------------------------- 6. salida ------------------------------------
return [{
  json: {
    hasAlerts,
    message,
    summary: {
      firstRun,
      activos: Object.keys(current).length,
      // En la primera corrida nada se comunica como novedad: es línea de base.
      nuevos:    firstRun ? 0 : nuevos.length,
      escalados: firstRun ? 0 : escalados.length,
      resueltos: firstRun ? 0 : resueltos.length,
      reportando: Object.keys(byHost)
    },
    // Esto es lo que se persiste y se vuelve a leer en la próxima corrida
    state: {
      updated: now,
      issues: current
    }
  }
}];

// Guardar sólo el bloque de estado, no el mensaje ni el resumen:
// el nodo 'Evaluar' de la próxima corrida espera {updated, issues}.
// $input.first() y no $json: en modo "Run Once for All Items" (el de
// por defecto) $json no existe y la rama del estado se cortaba sin guardar.
return [{ json: $input.first().json.state }];
